INSERT INTO "scans" VALUES(1,'9780134092669','Computer Systems','{"title":"Computer Systems","author":"Bryant, Randal E.","publisher":"Addison-Wesley","date":"2015-03-02","pages":"1120","isbn13":"9780134092669","isbn10":"013409266X","ddc":"-","lcc":"-","callNumber":"004 B103 c","description":"&>standalone product; MasteringEngineering® does not come packaged with this content. If you would like to purchase both the physical text and MasteringEngineering search for 0134123832 / 9780134123837 Computer Systems: A Programmer''s Perspective plus MasteringEngineering with Pearson eText -- Access Card Package, 3/e Package consists of: 013409266X/9780134092669 Computer Systems: A Programmer''s Perspective, 3/e 0134071921/9780134071923 MasteringEngineering with Pearson eText -- Standalone Access Card -- for Computer Systems: A Programmer''s Perspective, 3/e MasteringEngineering should only be purchased when required by an instructor. For courses in Computer Science and Programming Computer systems: A Programmer''s Perspective explains the underlying elements common among all computer systems and how they affect general application performance. Written from the programmer''s perspective, this book strives to teach readers how understanding basic elements of computer systems and executing real practice can lead them to create better programs. Spanning across computer science themes such as hardware architecture, the operating system, and systems software, the Third Edition serves as a comprehensive introduction to programming. This book strives to create programmers who understand all elements of computer systems and will be able to engage in any application of the field--from fixing faulty software, to writing more capable programs, to avoiding common flaws. It lays the groundwork for readers to delve into more intensive topics such as computer architecture, embedded systems, and cybersecurity. This book focuses on systems that execute an x86-64 machine code, and recommends that programmers have access to a Linux system for this course. Programmers should have basic familiarity with C or C++. Also available with MasteringEngineering MasteringEngineering is an online homework, tutorial, and assessment system, designed to improve results through personalized learning. This innovative online program emulates the instructor''s office hour environment, engaging and guiding students through engineering concepts with self-paced individualized coaching With a wide range of activities available, students can actively learn, understand, and retain even the most difficult concepts. Students, if interested in purchasing this title with MasteringEngineering, ask your instructor for the correct package ISBN and Course ID. Instructors, contact your Pearson representative for more information.","language":"English","subjects":"Computers","series":"-","publisherString":"- : Addison-Wesley, 2015","collation":"1120 p.","classification":"004","edition":"","specificDetail":"Addison-Wesley","gmd":"Text","infoLink":"http://books.google.co.id/books?id=7-IaogEACAAJ&dq=isbn:9780134092669&hl=&source=gbs_api","cover":"http://books.google.com/books/content?id=7-IaogEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api","isPartialData":true,"dataSource":"google-only","meta":{"isbn":"9780134092669","sources":{"google":true,"openlibrary":false,"loc":false},"fetchDuration":415,"totalDuration":1273,"timestamp":"2025-11-21T00:57:00.665Z"}}','2025-11-21 00:57:00');
